 const create=()=>{if(!adding||!newTitle.trim()||lists.find(list=>list.id===adding)?.kind==='ai')return;const listId=adding;const title=newTitle.trim();const card:Card={id:crypto.randomUUID(),listId,title,description:'',priority:'medium',labels:[],dueDate:null,completed:false,position:cards.filter(c=>c.listId===listId).length+1,checklist:[],comments:[],customFields:{},dependencies:[],attachments:[]};setNewTitle('');setAdding(null);commit([...cards,card]);if(repo&&!testMode)void runMutation(async()=>{await repo.createCard(board.id,listId,card.title,card.position)})};
