 const moveBoardList=(list:List)=>{const choices=lists.filter(l=>!l.isArchived).sort((a,b)=>a.position-b.position);const raw=window.prompt(`Move "${list.title}" to position (1-${choices.length}):`,String(choices.findIndex(l=>l.id===list.id)+1));if(raw===null)return;const position=Number(raw);if(!Number.isInteger(position)||position<1||position>choices.length){setMutationError('Enter a valid list position');return}const target=choices[position-1];if(!target||target.id===list.id)return;const next=moveList(lists,list.id,target.id);const changed=next.find(l=>l.id===list.id);if(!changed)return;setLists(next);if(repo&&!testMode)void runMutation(async()=>{await repo.reorderList(list.id,changed.position)})};
